CREATE COLUMN TABLE "TEST_AP"."ITR1" ("ReconNum" INTEGER CS_INT NOT NULL , "LineSeq" INTEGER CS_INT NOT NULL , "ShortName" NVARCHAR(15), "TransId" INTEGER CS_INT, "TransRowId" INTEGER CS_INT, "SrcObjTyp" NVARCHAR(20), "SrcObjAbs" INTEGER CS_INT, "ReconSum" DECIMAL(21,6) CS_FIXED, "ReconSumFC" DECIMAL(21,6) CS_FIXED, "ReconSumSC" DECIMAL(21,6) CS_FIXED, "FrgnCurr" NVARCHAR(3), "SumMthCurr" DECIMAL(21,6) CS_FIXED, "IsCredit" NVARCHAR(1), "Account" NVARCHAR(15), "CashDisSum" DECIMAL(21,6) CS_FIXED, "WTSum" DECIMAL(21,6) CS_FIXED, "WTSumFC" DECIMAL(21,6) CS_FIXED, "WTSumSC" DECIMAL(21,6) CS_FIXED, "ExpSum" DECIMAL(21,6) CS_FIXED, "ExpSumFC" DECIMAL(21,6) CS_FIXED, "ExpSumSC" DECIMAL(21,6) CS_FIXED, "netBefDisc" DECIMAL(21,6) CS_FIXED, "MIEntry" INTEGER CS_INT DEFAULT 0, "MIType" NVARCHAR(20), "InstID" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("ReconNum", "LineSeq")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ITR1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$TransId$TransRowId$','TransId','TransRowId'));
ALTER TABLE "TEST_AP"."ITR1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$SrcObjTyp$SrcObjAbs$','SrcObjTyp','SrcObjAbs'));
